import {omicsEntries,omicsGroups,omicsReferences} from './omics-data.js';
import {OmicsModel,modelNotes} from './omics-model.js';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function directoryHTML(selected,group){const g=omicsGroups.find(g=>g[0]===group);return `<div class="atlas-intro"><div><span class="eyebrow">THE OMICS ATLAS</span><h2>生命的不同层次，都有入口</h2></div><span class="atlas-count">${omicsEntries.length}<small>研究方向</small></span></div><p class="atlas-scope">从分子到群落，从细胞到环境。按六个区域探索；分支之间存在交叉，单细胞与空间属于观察尺度。这里持续扩展，不将组学限定成一份封闭名单。</p><div class="atlas-groups" aria-label="组学分类">${omicsGroups.map(([id,name])=>`<button data-omics-group="${id}" aria-pressed="${id===group}">${name}<small>${omicsEntries.filter(o=>o.group===id).length}</small></button>`).join('')}</div><p class="atlas-group-caption">${g[2]}</p><div class="atlas-topics">${omicsEntries.filter(o=>o.group===group).map(o=>`<button data-topic="${o.id}" class="${selected===o.id?'selected':''}" ${selected===o.id?'aria-current="true"':''}><strong>${o.name}</strong><small>${o.en}</small></button>`).join('')}</div>`;}
export function readerHTML(o){return `<div class="reader-heading"><span class="eyebrow">${omicsGroups.find(g=>g[0]===o.group)[1]} / ${o.en}</span><h2>${o.name}：从对象到技术</h2><p>${o.summary}</p></div><nav class="reader-jumps" aria-label="本节内容"><a href="#omics-research">研究什么</a><a href="#omics-techniques">主要技术</a><a href="#omics-comparison">技术对比</a><a href="#omics-case">实例与解读</a></nav><section id="omics-research"><h3>通常研究哪些问题？</h3><ol class="omics-questions">${o.research.map(s=>`<li>${s}</li>`).join('')}</ol></section><section id="omics-techniques"><h3>从样本到数据，主要技术怎么做？</h3><p>先看测量对象与输出，再比较覆盖、分辨率和适用问题。方法名称相近，不代表测到同一种信息。</p><div class="technique-cards">${o.techniques.map((t,i)=>`<article><span class="eyebrow">METHOD 0${i+1}</span><h4>${t.name}</h4><p><b>基本原理</b>${t.principle}</p><p><b>得到什么</b>${t.output}</p><p><b>适合研究</b>${t.best}</p><p><b>选择时考虑</b>${t.tradeoff}</p><button class="outline" data-lab-tech="${i}">查看实验流程 ↑</button></article>`).join('')}</div></section><section id="omics-comparison"><h3>把两种技术放在一起比较</h3><p>可以比较本方向内的不同方法，也可以跨方向比较，看看它们能否共同回答你的问题。</p><div class="comparison-pickers"><label>技术 A<select id="compare-a">${o.techniques.map((t,i)=>`<option value="${i}">${t.name}</option>`).join('')}</select></label><label>技术 B 所属方向<select id="compare-topic">${omicsEntries.map(x=>`<option value="${x.id}" ${x.id===o.id?'selected':''}>${x.name}</option>`).join('')}</select></label><label>技术 B<select id="compare-b"></select></label></div><div id="comparison-result"></div></section><section class="lesson-example" id="omics-case"><h3>用一个研究情境理解</h3><p>${o.example}</p></section><section class="lesson-confusion"><h3>读结果时，先分清这件事</h3><p>${o.caution}</p></section><section class="omics-workflow-note"><h3>共通的研究顺序</h3><p>明确问题 → 选择独立样本与对照 → 确定采样及测量方法 → 检查质量与批次 → 分析效应与不确定性 → 用其他证据验证解释。</p></section><div class="omics-sources"><h3>继续阅读与方法来源</h3>${o.refs.map(id=>`<a href="${omicsReferences[id].url}" target="_blank" rel="noopener noreferrer">${omicsReferences[id].label} ↗</a>`).join('')}</div><div class="reader-actions"><button class="primary" data-practice>检查我是否理解 →</button><button class="outline" data-mode="structure">返回三维模型 ↑</button></div>`;}
export function bindComparison(root,o){const a=root.querySelector('#compare-a'),topic=root.querySelector('#compare-topic'),b=root.querySelector('#compare-b');const update=()=>{const other=omicsEntries.find(x=>x.id===topic.value),ta=o.techniques[+a.value],tb=other.techniques[+b.value];root.querySelector('#comparison-result').innerHTML=`<div class="comparison-scroll" tabindex="0" role="region" aria-label="技术对比表，可横向滚动"><table class="comparison-table"><thead><tr><th>比较维度</th><th>${ta.name}</th><th>${tb.name}</th></tr></thead><tbody>${[['principle','测量原理'],['output','数据输出'],['best','适合的问题'],['tradeoff','技术取舍']].map(([key,label])=>`<tr><th>${label}</th><td>${ta[key]}</td><td>${tb[key]}</td></tr>`).join('')}</tbody></table></div><p class="comparison-insight">${topic.value===o.id?'同一研究方向也有不同测量范围；根据需要的证据选择，而不是只比较名称或通量。':`${o.name}与${other.name}观察的是不同问题或层次。联合分析前，要确认样本、时间点和数据单位能否对应。`}</p>`;};const populate=()=>{const other=omicsEntries.find(x=>x.id===topic.value);b.innerHTML=other.techniques.map((t,i)=>`<option value="${i}" ${i===(other.id===o.id?1:0)?'selected':''}>${t.name}</option>`).join('');update();};a.addEventListener('change',update);b.addEventListener('change',update);topic.addEventListener('change',populate);populate();}

export const demos={
 sequence:{name:'读段与序列覆盖',choices:['短读段','长读段'],steps:['原分子含重复与独特片段','测量得到局部读段','将读段与参考或其他读段对应','跨越重复可增加连续信息'],note:'固定的一条抽象序列。读段长度演示不代表真实平台参数或实际覆盖深度。'},
 chromatin:{name:'同一染色质，不同读数',choices:['ATAC：可及性','ChIP：特定靶标','DNA 甲基化'],steps:['在相同坐标上定义研究区域','实验选择可及 DNA、靶标或修饰','把测量信号定位回基因组','不同轨迹代表不同信息'],note:'峰、位点与颜色均为教学模拟。轨迹不是表达量，也不表示三种测量之间固定的因果关系。'},
 mass:{name:'质谱采集策略',choices:['DDA：选择前体','DIA：扫描窗口','靶向：指定目标'],steps:['样本产生一组可检测离子','选定前体、窗口或预设目标','采集相关信号并进行鉴定','得到不同覆盖与定量信息'],note:'模拟前体谱与采集选择；真实鉴定还依赖碎片谱、分离、数据库与错误控制。'},
 community:{name:'相对丰度与绝对数量',choices:['A 数量增加','B 数量减少'],steps:['先观察两个群体的初始数量','改变其中一个群体的数量','重新计算各自占总量的比例','相同比例变化可有不同原因'],note:'A、B 是虚构群体，数量为任意教学单位；图中所有百分比由当前数量计算。'},
 single:{name:'混合样本与单细胞',choices:['整体平均','保留每个细胞'],steps:['组织包含两类不同状态的细胞','测量细胞的一个模拟信号','整体平均会合并差异','保留细胞单位才能看到分布'],note:'模拟信号仅说明异质性；一个细胞不是一位独立供者，未展示真实测序掉零。'},
 spatial:{name:'空间点位与细胞混合',choices:['较粗点位','较细点位'],steps:['组织中的细胞信号存在梯度','划分空间测量单位','汇总每个单位中的信号','点位范围影响能区分的局部差异'],note:'教学网格的空间单位是人为设定。较细不自动意味着更准确，还要考虑灵敏度和分割。'},
 contact:{name:'关系网络与证据阈值',choices:['保留较多候选边','只看较强信号'],steps:['节点对应研究对象','测量或推断节点之间的关系','按证据强弱筛选候选边','关系图帮助提出待验证假设'],note:'虚构网络用于理解阈值。线长不是物理距离，边也不自动代表直接结合或因果。'},
 flux:{name:'相同存量，不同流量',choices:['较慢周转','较快周转'],steps:['水池式模型中的总量保持不变','用标记物替换流入的未标记物','不同流速产生不同标记进程','结合时间与模型估计周转'],note:'定量示例采用单池、恒定总量、完全混合模型 f(t)=1−exp(−kt)。参数任意，不能外推为真实代谢通量。'}
};
const svgText=(x,y,s,size=15)=>`<text x="${x}" y="${y}" font-size="${size}" fill="#52667e" text-anchor="middle">${escape(s)}</text>`;
const rect=(x,y,w,h,c,rx=5)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${c}"/>`;
const circle=(x,y,r,c)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
export function demoSVG(id,choice,p){let b='';const x=p/100;
 if(id==='sequence'){const seq='ACGTACGTGGGGGGGGACGTACGT';for(let i=0;i<24;i++)b+=rect(52+i*25,55,23,35,i>=8&&i<16?'#b3a2b9':'#99aebc')+svgText(63+i*25,78,seq[i],13);const len=choice===0?4:12;for(let r=0;r<5;r++){const start=(r*4+Math.floor(x*5))%(24-len+1);b+=rect(52+start*25,120+r*25,len*25-2,14,r===2?'#b4aa95':'#a4b8ab');}b+=svgText(350,285,choice===0?'短片段在重复区域可能有多个对应位置':'较长片段可跨越重复并连接两侧信息');}
 else if(id==='chromatin'){b+=rect(55,100,590,6,'#b7c4ce');for(let i=0;i<7;i++)b+=circle(95+i*82,100,25,'#aca0b8');for(let i=0;i<24;i++){const h=choice===0?([12,5,36,46,15,7][i%6]):choice===1?([6,7,13,52,40,8][i%6]):([28,7,40,12][i%4]);b+=rect(65+i*24,250-h,choice===2?5:17,h,choice===2?'#b4a085':'#92aaba');}b+=rect(55,150,590*x,3,'#c4b293')+svgText(350,40,demos[id].choices[choice])+svgText(350,287,choice===2?'位点的修饰比例示意':'区域富集信号示意');}
 else if(id==='mass'){for(let i=0;i<18;i++){const h=25+(i*43)%130,left=40+x*500,selected=choice===0?(h>=110&&i<2+x*18):choice===1?(65+i*32+4.5>=left&&65+i*32+4.5<=left+110):[3,9,15].includes(i);b+=rect(65+i*32,240-h,9,h,selected?'#9b8eae':'#ccd5df');}if(choice===1)b+=`<rect x="${40+x*500}" y="65" width="110" height="180" fill="#a8b9c22b" stroke="#a1b3bf"/>`;b+=svgText(350,280,'质荷比 m/z →　　纵向：模拟离子强度')+svgText(350,36,demos[id].choices[choice]);}
 else if(id==='community'){const a=choice===0?20+40*x:20,bb=choice===0?80:80-60*x,total=a+bb;for(let i=0;i<Math.round(a/4);i++)b+=circle(100+i%7*24,80+Math.floor(i/7)*25,9,'#a79bb8');for(let i=0;i<Math.round(bb/4);i++)b+=circle(390+i%7*24,80+Math.floor(i/7)*25,9,'#9eafa6');b+=svgText(175,190,`A：${a.toFixed(0)} 单位`)+svgText(465,190,`B：${bb.toFixed(0)} 单位`)+rect(90,218,520*a/total,30,'#a79bb8')+rect(90+520*a/total,218,520*bb/total,30,'#9eafa6')+svgText(350,282,`A 占 ${(a/total*100).toFixed(1)}% · B 占 ${(bb/total*100).toFixed(1)}% · 总量 ${total.toFixed(0)}`);}
 else if(id==='single'){const vals=Array.from({length:12},(_,i)=>i<6?2:8),mean=5;vals.forEach((v,i)=>{b+=circle(80+i*49,70,17,i<6?'#b6a5bc':'#94afbc');const h=(choice===0?mean:v)*17*x;b+=rect(65+i*49,245-h,30,h,i<6?'#b6a5bc':'#94afbc');});b+=svgText(350,285,choice===0?'两类细胞合并后：每个细胞的平均信号为 5':'保留细胞单位：一组为 2，另一组为 8');}
 else if(id==='spatial'){const size=choice===0?3:1;for(let y=0;y<6;y++)for(let c=0;c<12;c++){const base=Math.floor(c/size)*size+(size-1)/2,signal=(base/11)*x;b+=rect(85+c*43,38+y*35,40,32,`rgb(${Math.round(226-signal*77)},${Math.round(233-signal*70)},${Math.round(239-signal*59)})`,3);}b+=svgText(350,285,choice===0?'相邻细胞被汇总进同一个较大点位':'较细单位保留了更多局部差异');}
 else if(id==='contact'){const pts=Array.from({length:9},(_,i)=>[350+Math.cos(i*6.28/9)*205,150+Math.sin(i*6.28/9)*100]);for(let i=0;i<9;i++)for(let j=i+1;j<9;j++){const strength=((i*13+j*17)%10)/10;if(strength>(choice===0?.2:.65)&&j<=2+x*7)b+=`<path d="M${pts[i][0]} ${pts[i][1]}L${pts[j][0]} ${pts[j][1]}" stroke="#a9b8c5" stroke-width="${1+strength*3}"/>`;}pts.forEach(([xx,y],i)=>{b+=circle(xx,y,19,i%2?'#9bafbd':'#afa1b7')+svgText(xx,y+5,String(i+1),13);});b+=svgText(350,292,'更严格的阈值减少候选边，也可能遗漏较弱关系');}
 else{const k=choice===0?.6:2.4,f=1-Math.exp(-k*x);b+=rect(220,65,260,165,'#dde5eb',18)+rect(226,225-155*f,248,155*f,'#9cb5ac',10)+svgText(350,45,'总量固定：100 单位')+svgText(350,265,`标记比例 ${(f*100).toFixed(1)}% · 时间 ${x.toFixed(2)} · 周转参数 ${k}`)+svgText(350,298,'流入与流出速率相等，总量不变');}
 return `<svg viewBox="0 0 700 320" role="img" aria-label="${demos[id].name}教学模拟" xmlns="http://www.w3.org/2000/svg">${b}</svg>`;
}
export class OmicsStudio{
 constructor(root,o,mode,techIndex=0){this.root=root;this.o=o;this.mode=mode;this.p=0;this.choice=0;this.demo=o.assay;this.frame=null;this.playing=false;this.destroyed=false;this.techIndex=Math.min(techIndex,o.techniques.length-1);this.abort=new AbortController();const opts={signal:this.abort.signal};
 root.innerHTML=mode==='structure'?`<div class="omics-model-heading"><div><span class="eyebrow">INTERACTIVE SPECIMEN</span><h3>${o.name} · 观察研究对象</h3></div><a class="model-atlas-link" href="#omics-atlas">40 个方向 ↓</a></div><div class="omics-canvas" tabindex="0" aria-label="组学三维模型，拖动或方向键旋转，加减键缩放，点击模型查看解释"></div><div class="omics-model-tools"><button data-om="rotate" aria-pressed="false">自动旋转</button><button data-om="minus" aria-label="缩小组学模型">−</button><button data-om="plus" aria-label="放大组学模型">＋</button><button data-om="reset">复位</button><span>拖动旋转 · 滚轮缩放</span></div><div class="omics-parts" aria-label="模型结构">${modelNotes[o.model].map(([label],i)=>`<button data-part="${i}">${label}</button>`).join('')}</div><p class="omics-part-detail" aria-live="polite"></p><p class="omics-model-note">程序生成的教学示意 · 非真实结构解析 · 不同方向可共享同一研究对象模型</p><button class="outline full" data-mode="process">进入技术实验台 →</button>`:this.processHTML();
 if(mode==='structure'){const pick=i=>{root.querySelector('.omics-part-detail').textContent=modelNotes[o.model][i][1];root.querySelectorAll('[data-part]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.part===i)));};try{this.model=new OmicsModel(root.querySelector('.omics-canvas'),o.model,pick);}catch{root.querySelector('.omics-canvas').innerHTML='<div class="omics-fallback">三维显示暂不可用。下方结构按钮与技术实验台仍可学习。</div>';pick(0);}root.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.part!==undefined){this.model?this.model.select(+b.dataset.part):pick(+b.dataset.part);}if(b?.dataset.om&&this.model){const a=b.dataset.om;if(a==='plus'||a==='minus')this.model.zoom(a==='plus'?.85:1.18);if(a==='reset'){this.model.reset();root.querySelector('[data-om="rotate"]').setAttribute('aria-pressed','false');}if(a==='rotate'){this.model.controls.autoRotate=!this.model.controls.autoRotate;b.setAttribute('aria-pressed',String(this.model.controls.autoRotate));}}},opts);}
 else{this.drawWorkflow();this.configureDemo();root.querySelector('#omics-technique').addEventListener('change',e=>{this.techIndex=+e.target.value;this.drawWorkflow();},opts);root.querySelector('#omics-demo').addEventListener('change',e=>{this.pause();this.demo=e.target.value;this.choice=0;this.p=0;this.configureDemo();},opts);root.querySelector('#omics-strategy').addEventListener('change',e=>{this.choice=+e.target.value;this.draw();},opts);root.querySelector('#omics-seek').addEventListener('input',e=>{this.pause();this.p=+e.target.value;this.draw();},opts);root.addEventListener('click',e=>{const b=e.target.closest('[data-lab]');if(!b)return;const a=b.dataset.lab;if(a==='play'){this.playing?this.pause():this.play();}else{this.pause();this.p=a==='reset'?0:Math.max(0,Math.min(100,this.p+(a==='next'?25:-25)));this.draw();}},opts);document.addEventListener('visibilitychange',()=>{if(document.hidden)this.pause();},opts);}
 }
 processHTML(){return `<div class="omics-lab-header"><span class="eyebrow">FROM SAMPLE TO EVIDENCE</span><h3>技术实验台</h3><label>当前方向的方法<select id="omics-technique">${this.o.techniques.map((t,i)=>`<option value="${i}" ${i===this.techIndex?'selected':''}>${t.name}</option>`).join('')}</select></label></div><div id="omics-workflow"></div><div class="lab-simulator"><h4>动手观察一个测量原理</h4><p class="lab-scope">下方为跨技术原理演示，与上方具体实验流程分开阅读。切换策略，再播放或拖动进度比较结果。</p><div class="lab-selects"><label>演示主题<select id="omics-demo">${Object.entries(demos).map(([id,d])=>`<option value="${id}" ${id===this.demo?'selected':''}>${d.name}</option>`).join('')}</select></label><label>观察策略<select id="omics-strategy"></select></label></div><div class="omics-demo-canvas"></div><div class="lab-step" aria-live="polite"></div><label class="lab-range" for="omics-seek">演示进度 <output></output><input id="omics-seek" type="range" min="0" max="100" step="1" value="0"></label><div class="lab-buttons"><button data-lab="prev">← 上一步</button><button data-lab="play" aria-pressed="false">播放</button><button data-lab="next">下一步 →</button><button data-lab="reset">重播</button></div><p class="lab-demo-note"></p></div><a class="outline full" href="#omics-comparison">查看技术对比 ↓</a>`;}
 drawWorkflow(){const t=this.o.techniques[this.techIndex];this.root.querySelector('#omics-workflow').innerHTML=`<ol class="lab-workflow"><li><small>01 · 问题</small><p>${t.best}</p></li><li><small>02 · 测量</small><p>${t.principle}</p></li><li><small>03 · 数据</small><p>${t.output}</p></li><li><small>04 · 解读</small><p>${t.tradeoff}</p></li></ol>`;}
 configureDemo(){const d=demos[this.demo];this.root.querySelector('#omics-strategy').innerHTML=d.choices.map((x,i)=>`<option value="${i}">${x}</option>`).join('');this.lastStep=-1;this.draw();}
 draw(){if(this.destroyed)return;const d=demos[this.demo],step=Math.min(3,Math.floor(this.p/25));this.root.querySelector('.omics-demo-canvas').innerHTML=demoSVG(this.demo,this.choice,this.p);if(step!==this.lastStep){this.root.querySelector('.lab-step').textContent=`${step+1} / 4 · ${d.steps[step]}`;this.lastStep=step;}this.root.querySelector('#omics-seek').value=this.p;this.root.querySelector('output').textContent=Math.round(this.p)+'%';this.root.querySelector('.lab-demo-note').textContent=d.note;this.root.querySelector('[data-lab="prev"]').disabled=this.p===0;this.root.querySelector('[data-lab="next"]').disabled=this.p===100;}
 play(){if(this.p>=100)this.p=0;this.playing=true;this.last=performance.now();this.root.querySelector('[data-lab="play"]').textContent='暂停';this.root.querySelector('[data-lab="play"]').setAttribute('aria-pressed','true');const tick=t=>{if(!this.playing||this.destroyed)return;this.p=Math.min(100,this.p+Math.min(100,t-this.last)/160);this.last=t;this.draw();if(this.p>=100)this.pause();else this.frame=requestAnimationFrame(tick);};this.frame=requestAnimationFrame(tick);}
 pause(){this.playing=false;cancelAnimationFrame(this.frame);const b=this.root.querySelector('[data-lab="play"]');if(b){b.textContent='播放';b.setAttribute('aria-pressed','false');}}
 getState(){return{topic:this.o.id,mode:this.mode,model:this.model?.getState()||null,demo:this.demo,choice:this.choice,progress:this.p,playing:this.playing,technique:this.techIndex};}
 destroy(){this.destroyed=true;this.pause();this.abort.abort();this.model?.destroy();}
}
